'use strict';
const P=NewclearusPricing,$=id=>document.getElementById(id),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let privacyChoice=null,state=P.normalize({packageIndex:0}),welcomeReturn=null,locationEpoch=0;
try{const v=JSON.parse(localStorage.getItem('newclearus-privacy-v2'));if(v?.version===2)privacyChoice=v;if(privacyChoice?.storage){const saved=JSON.parse(localStorage.getItem('newclearus-scenario-v2'));if(saved?.version===11)state=P.normalize(saved);}else if(privacyChoice?.market)state.region=privacyChoice.market==='usa'?'usa':'uk';}catch{}
const money=v=>new Intl.NumberFormat(state.region==='usa'?'en-US':'en-GB',{style:'currency',currency:state.region==='usa'?'USD':'GBP'}).format(v);
function save(){if(privacyChoice?.storage)try{localStorage.setItem('newclearus-scenario-v2',JSON.stringify(state));}catch{}}
function toast(t){$('toast').textContent=t;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,3500);}
function toggleMenu(b){const open=$('mainnav').classList.toggle('open');b.setAttribute('aria-expanded',String(open));}function closeMenu(){$('mainnav').classList.remove('open');document.querySelector('.mobile-menu').setAttribute('aria-expanded','false');}
function openConsent(){if($('welcome-dialog').open)return;locationEpoch++;welcomeReturn=document.activeElement;$('welcome-market').value=state.region;$('location-opt-in').checked=privacyChoice?.location===true;$('remember-opt-in').checked=privacyChoice?.storage===true;$('confirm-market').checked=false;$('welcome-dialog').showModal();}
function setRegion(v){state.region=v==='usa'?'usa':'uk';$$('[data-region]').forEach(b=>{const on=b.dataset.region===state.region;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on));});$('market-note').textContent=(state.region==='usa'?'USA · USD':'United Kingdom · GBP')+' · 12-month contracts. Your market changes prices, not your team location.';$('welcome-market').value=state.region;renderPrices();save();window.dispatchEvent(new CustomEvent('newclearus-market',{detail:state.region}));}
$('welcome-market').addEventListener('change',()=>{locationEpoch++;$('location-result').textContent='Using your selected market. Confirm it below to continue.';});
$('location-opt-in').addEventListener('change',async ev=>{const requestEpoch=++locationEpoch;if(!ev.target.checked){$('location-result').textContent='Location suggestion is off. Select your market manually.';return;}$('location-result').textContent='Checking your approximate country…';let country=null;try{const r=await fetch('/api/visitor-market',{headers:{'X-Newclearus-Location-Consent':'yes'},cache:'no-store',signal:AbortSignal.timeout(5000)});if(r.ok)country=(await r.json()).country;}catch{}
 if(!$('location-opt-in').checked||requestEpoch!==locationEpoch)return;const result=P.suggestMarket({country,language:navigator.language,timezone:Intl.DateTimeFormat().resolvedOptions().timeZone});if(result.market){$('welcome-market').value=result.market;$('location-result').textContent='Suggested '+(result.market==='usa'?'USA':'UK')+' from '+result.source+'. Confirm or change it below.';}else $('location-result').textContent=result.source+'. UK/USA prices are based on the client market you choose.';});
$('welcome-form').addEventListener('submit',ev=>{ev.preventDefault();if(!ev.currentTarget.reportValidity())return;locationEpoch++;privacyChoice={version:2,location:$('location-opt-in').checked,storage:$('remember-opt-in').checked,market:$('welcome-market').value,time:Date.now()};try{localStorage.setItem('newclearus-privacy-v2',JSON.stringify(privacyChoice));if(!privacyChoice.storage){localStorage.removeItem('newclearus-scenario-v2');localStorage.removeItem('newclearus-scenario-v1');}}catch{}setRegion(privacyChoice.market);$('welcome-dialog').close();if(welcomeReturn?.isConnected)welcomeReturn.focus();});
$('welcome-dialog').addEventListener('cancel',ev=>{if(!privacyChoice)ev.preventDefault();});
function makeICT(){
 $('ict-options').innerHTML=P.ictNames.map((name,i)=>`<div class="ict-service-row"><label class="service-select"><input id="ict-select-${i}" type="checkbox" data-ict="${i}"><span>${esc(name)}<small data-ict-rate></small></span></label><div id="ict-fields-${i}" class="ict-service-fields"><label class="field">Delivery type<select id="ict-mode-${i}"><option value="ongoing">Ongoing service</option><option value="project">Once-off project</option></select></label><label class="field"><span id="ict-hours-label-${i}">Hours / person / month</span><input id="ict-hours-${i}" type="number" min="0" max="1000" step="0.5" aria-label="${esc(name)} hours per person"></label><span class="row-cost" id="ict-cost-${i}"></span></div></div>`).join('');
 P.ictNames.forEach((_,i)=>{$('ict-select-'+i).addEventListener('change',ev=>{state.ictSelected[i]=ev.target.checked;syncICT();renderTotals();save();});$('ict-mode-'+i).addEventListener('change',ev=>{state.ictModes[i]=ev.target.value;syncICT();renderTotals();save();});$('ict-hours-'+i).addEventListener('input',ev=>{state.ictHours[i]=P.number(ev.target.value,0,1000,0.5);renderTotals();save();});$('ict-hours-'+i).addEventListener('change',ev=>ev.target.value=state.ictHours[i]);});
}
function syncICT(){P.ictNames.forEach((_,i)=>{$('ict-select-'+i).checked=state.ictSelected[i];$('ict-fields-'+i).hidden=!state.ictSelected[i];$('ict-mode-'+i).value=state.ictModes[i];$('ict-hours-'+i).value=state.ictHours[i];$('ict-hours-label-'+i).textContent=state.ictModes[i]==='project'?'Total project hours / person':'Hours / person / month';});$('ict-count').value=state.ictCount;}
function renderEOR(){
 const e=P.eor(state);$('eor-count').value=state.eorCount;$('eor-mode').value=state.eorMode;$('eor-recurring').hidden=state.eorMode==='project';$('eor-project-note').hidden=state.eorMode!=='project';
 $('eor-package-choices').innerHTML=P.packages.map((p,i)=>`<label class="package-choice"><input type="checkbox" data-eor-package="${i}" ${state.packageIndex===i?'checked':''}><span><strong>${p.name}</strong><small>${p.services.map(j=>P.services[j].name).join(' · ')}</small></span><b>${money(P.packageFee(i,state.region))}<small>/ employee / month${state.region==='usa'?' · indicative':''}</small></b></label>`).join('')+`<label class="package-choice"><input type="checkbox" data-eor-package="custom" ${state.packageIndex===null?'checked':''}><span><strong>Build your own</strong><small>Choose services at their itemised rates.</small></span></label>`;
 $$('[data-eor-package]').forEach(el=>el.addEventListener('change',()=>{state.packageIndex=el.dataset.eorPackage==='custom'?null:+el.dataset.eorPackage;state.eorSelected=state.packageIndex===null?[0,1]:[0,...P.packages[state.packageIndex].services];renderEOR();renderTotals();save();}));
 $('eor-options').innerHTML=P.services.map((o,i)=>{const included=e.included.includes(i);return `<label class="eor-service-option"><input type="checkbox" data-eor-service="${i}" ${e.selection.includes(i)?'checked':''} ${included?'disabled':''}><span>${esc(o.name)}<small>${included?'Included in your package':esc(o.detail)}</small></span><span class="service-fee">${included?'Included':money(o.price[state.region==='usa'?1:0])}<small>${included?'':o.once?'once off / hire':'/ employee / month'}</small></span></label>`;}).join('');
 $$('[data-eor-service]').forEach(el=>el.addEventListener('change',()=>{const i=+el.dataset.eorService;state.eorSelected=state.eorSelected.filter(x=>x!==i);if(el.checked)state.eorSelected.push(i);renderEOR();renderTotals();document.querySelector('[data-eor-service="'+i+'"]')?.focus();save();}));
 $('eor-selection-note').textContent='Included package services are charged once through the package price. Optional extras add their listed flat fee. Recruitment is a once-off charge. Salaries and employer costs are separate.';
}
function choosePackage(i){state.wantEOR=true;state.eorMode='ongoing';state.packageIndex=i;state.eorSelected=i===null?[0,1]:[0,...P.packages[i].services];renderAll();save();$('eor-builder').scrollIntoView({behavior:'smooth'});}
function renderCatalogue(){
 $('ict-package-cards').innerHTML=P.ictPackages.map((p,i)=>`<article class="card"><span class="tag">FLEXIBLE HOURS · 12-MONTH AGREEMENT</span><h4>${p.name}</h4><p>${p.description}</p><ul>${p.services.map(j=>'<li>'+P.ictNames[j]+'</li>').join('')}</ul><p class="note">${money(P.rate(state.region))}/working hour planning rate. Set team size and hours in your quote.</p><button class="btn" data-ict-package="${i}">Select this combination</button></article>`).join('');
 $$('[data-ict-package]').forEach(b=>b.addEventListener('click',()=>{state.wantICT=true;state.ictSelected=P.ictNames.map((_,i)=>P.ictPackages[+b.dataset.ictPackage].services.includes(i));renderAll();save();$('it-builder').scrollIntoView({behavior:'smooth'});}));
 $('eor-prices').innerHTML=P.packages.map((p,i)=>`<article class="card"><span class="tag">12-MONTH CONTRACT</span><h4>${p.name}</h4><div class="price">${money(P.packageFee(i,state.region))}</div><span class="muted">/ employee / month${state.region==='usa'?' · indicative':''}</span><ul>${p.services.map(j=>'<li>'+P.services[j].name+'</li>').join('')}</ul><p class="note">Recruitment and the three-month security deposit are separate.</p><button class="btn" onclick="choosePackage(${i})">Select ${p.name}</button></article>`).join('')+`<article class="card"><span class="tag">CUSTOM SERVICES</span><h4>Build your own</h4><div class="price">Your mix.</div><p>Choose the EOR services you need at their itemised rates.</p><p class="note">Salaries do not change our flat service fees.</p><button class="btn" onclick="choosePackage(null)">Customise services</button></article>`;
 $('package-currency-note').textContent=state.region==='usa'?'USD package amounts are planning conversions at £1 = $1.27. Itemised USD service rates remain as listed. Confirm final USD package terms on the discovery call.':'Retained flat GBP package rates. Salary and employer costs are additional. All ongoing contracts are set at 12 months.';
 $('eor-service-catalogue').innerHTML=P.services.map(o=>`<article><h3>${esc(o.name)}</h3><p>${esc(o.detail)}</p><span>${money(o.price[state.region==='usa'?1:0])}${o.once?' once off / hire':' / employee / month'} · itemised rate</span></article>`).join('');
}
function row(label,value){return `<div class="line"><span>${esc(label)}</span><b>${esc(value)}</b></div>`;}
function renderTotals(){const t=P.total(state);$('summary-context').textContent=(state.region==='usa'?'USA / USD':'UK / GBP')+' · Existing team in '+({usa:'the USA',uk:'the UK',sa:'South Africa'}[state.teamLocation]);
 $('quote-lines').innerHTML=(state.wantICT?row('ICT projects · once off',money(t.ict.once))+row('ICT ongoing · monthly',money(t.ict.monthly)):'')+(state.wantEOR?row(state.eorMode==='project'?'Recruitment project · once off':'EOR recruitment · once off',money(t.eor.once))+row('EOR support · monthly',money(t.eor.monthly)):'')+row('All once-off service charges',money(t.once))+row('3-month deposit · service-fee portion',money(t.deposit));
 $('upfront-total').textContent=money(t.upfront);$('monthly-total').textContent=money(t.monthly);$('annual-total').textContent='12-month service fees + once-off charges: '+money(t.annual)+'. Excludes the security deposit, employee pay, statutory costs, taxes and separately scoped costs.';
 P.ictNames.forEach((_,i)=>{$('ict-cost-'+i).textContent=money(P.round(state.ictHours[i]*state.ictCount*P.rate(state.region)))+(state.ictModes[i]==='project'?' once off':' / month');});
 if(!$('quote-attached').hidden)$('quote-attached').textContent='Your current quote is attached: '+money(t.once)+' once off, '+money(t.monthly)+'/month, '+money(t.deposit)+' service-fee deposit.';
 updateReading();}
function renderPrices(){$('ict-rate').textContent=money(P.rate(state.region))+' / working hour';$$('[data-ict-rate]').forEach(el=>el.textContent=money(P.rate(state.region))+' / working hour · planning rate');renderEOR();renderCatalogue();renderTotals();}
function renderAll(){$('want-ict').checked=state.wantICT;$('want-eor').checked=state.wantEOR;$('it-builder').hidden=!state.wantICT;$('eor-builder').hidden=!state.wantEOR;$('quote-summary').hidden=!(state.wantICT||state.wantEOR);$('choose-note').hidden=state.wantICT||state.wantEOR;$('team-location').value=state.teamLocation;$('new-contract').checked=state.newContract;syncICT();renderPrices();}
function estimateText(){const t=P.total(state);return `NEWCLEARUS SERVICE ESTIMATE\nMarket: ${state.region==='usa'?'USA / USD':'UK / GBP'}\nExisting team location: ${{usa:'USA',uk:'UK',sa:'South Africa'}[state.teamLocation]}\nService agreement: 12 months\n\n`+(state.wantICT?`ICT: ${state.ictCount} people\n`+t.ict.lines.map(l=>`${l.name}: ${l.hours} total ${l.mode==='project'?'project hours':'hours/month'} at ${money(t.ict.hourly)}/hour = ${money(l.cost)} ${l.mode==='project'?'once off':'monthly'}`).join('\n')+'\n\n':'')+(state.wantEOR?`EOR: ${state.eorCount} South African hires\n${state.eorMode==='project'?'Once-off recruitment only':state.packageIndex===null?'Itemised services':P.packages[state.packageIndex].name}\nServices: ${t.eor.selection.map(i=>P.services[i].name).join(', ')||'None'}\n\n`:'')+`Once-off services: ${money(t.once)}\nOngoing monthly services: ${money(t.monthly)}\nThree-month security deposit, service-fee portion: ${money(t.deposit)}\nEstimated upfront service amount: ${money(t.upfront)}\n12-month service fees plus once-off charges: ${money(t.annual)} (deposit separate)\n\nSalaries, employer costs and related deposit are determined on the discovery call. EOR fees are flat regardless of employee pay. ICT licences, cloud consumption, hardware, standby and taxes are separate. ${state.region==='usa'?'USD EOR package amounts indicative at GBP1 = USD1.27. ':''}Final scope, rates, deposit treatment and payment schedule require a proposal. This is a planning estimate.`;}
function downloadText(text,name){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('attach-quote').addEventListener('click',()=>{$('quote-attached').hidden=false;renderTotals();$('contact').scrollIntoView({behavior:'smooth'});});$('download-quote').addEventListener('click',()=>downloadText(estimateText(),'Newclearus_Service_Estimate.txt'));
['want-ict','want-eor'].forEach(id=>$(id).addEventListener('change',ev=>{state[id==='want-ict'?'wantICT':'wantEOR']=ev.target.checked;renderAll();save();}));$('team-location').addEventListener('change',ev=>{state.teamLocation=ev.target.value;renderTotals();save();});$('new-contract').addEventListener('change',ev=>{state.newContract=ev.target.checked;renderTotals();save();});
for(const [id,key] of [['ict-count','ictCount'],['eor-count','eorCount']]){$(id).addEventListener('input',ev=>{state[key]=P.number(ev.target.value,1,5000);renderTotals();save();});$(id).addEventListener('change',ev=>ev.target.value=state[key]);}
$('eor-mode').addEventListener('change',ev=>{state.eorMode=ev.target.value;renderEOR();renderTotals();save();});$('ict-reset').addEventListener('click',()=>{state.ictCount=1;state.ictSelected=[true,false,false,false,false,false];state.ictHours=[1,1,1,1,1,1];state.ictModes=Array(6).fill('ongoing');renderAll();save();});$('eor-reset').addEventListener('click',()=>{state.eorCount=1;state.eorMode='ongoing';state.packageIndex=0;state.eorSelected=[0,1];renderAll();save();});
$$('[data-add-ict]').forEach(b=>b.addEventListener('click',()=>{state.wantICT=true;state.ictSelected[+b.dataset.addIct]=true;renderAll();save();$('it-builder').scrollIntoView({behavior:'smooth'});}));
function enquiryText(){const f=$('contact-form');return `Name: ${f.elements.name.value}\nWork email: ${f.elements.email.value}\nMessage: ${f.elements.message.value}\n\n${state.wantICT||state.wantEOR?estimateText():'Services to discuss on the discovery call.'}`;}
$('contact-form').addEventListener('submit',ev=>{ev.preventDefault();if(!ev.currentTarget.reportValidity())return;location.href='mailto:joinus@newclearus.com?subject='+encodeURIComponent('Newclearus services enquiry')+'&body='+encodeURIComponent(enquiryText());$('form-status').textContent='Review and send the draft in your email app. If it does not open, use Copy enquiry. Nothing has been sent by this website.';});$('copy-enquiry').addEventListener('click',async()=>{if(!$('contact-form').reportValidity())return;try{await navigator.clipboard.writeText(enquiryText());$('form-status').textContent='Enquiry copied. Paste it into an email to joinus@newclearus.com.';}catch{$('form-status').textContent='Copy unavailable. Use Open enquiry in your email app.';}});
function filterResources(){const q=$('resource-search').value.trim().toLowerCase(),region=$('resource-region').value,type=$('resource-type').value,items=NewclearusResources.filter(r=>(region==='all'||r.regions.includes(region))&&(type==='all'||r.type===type)&&(!q||(r.title+' '+r.description+' '+r.tags).toLowerCase().includes(q)));$('resource-grid').innerHTML=items.map(r=>`<article class="resource-card"><span class="resource-meta">${esc(r.label)} · ${r.regions.map(x=>({usa:'USA',uk:'UK',sa:'South Africa'}[x])).join(' / ')}</span><h3>${esc(r.title)}</h3><p>${esc(r.description)}</p><a href="${esc(r.href)}">${r.type==='calculator'?'Open calculator':r.type==='checklist'?'Use checklist':'Read resource'} ↗</a></article>`).join('');$('resource-count').textContent=items.length+' resource'+(items.length===1?'':'s')+' found';$('resource-empty').hidden=items.length>0;updateReading();}
['resource-search','resource-region','resource-type'].forEach(id=>$(id).addEventListener(id==='resource-search'?'input':'change',filterResources));$('resource-reset').addEventListener('click',()=>{$('resource-search').value='';$('resource-region').value='all';$('resource-type').value='all';filterResources();});
let readingFrame=0;function updateReading(){if(readingFrame)return;readingFrame=requestAnimationFrame(()=>{readingFrame=0;const range=document.documentElement.scrollHeight-innerHeight,percent=range<=0?100:Math.max(0,Math.min(100,Math.round(scrollY/range*100)));$('reading-percent').textContent=percent+'%';$('reading-fill').style.height=percent+'%';$('reading-progress').setAttribute('aria-valuenow',String(percent));$('progress').style.width=percent+'%';});}addEventListener('scroll',updateReading,{passive:true});addEventListener('resize',updateReading);new ResizeObserver(updateReading).observe(document.querySelector('main'));
function activateHash(){if(location.hash==='#privacy-choices')openConsent();if(location.hash==='#it-builder'){state.wantICT=true;renderAll();}if(location.hash==='#eor-builder'){state.wantEOR=true;renderAll();}if(['#it-builder','#eor-builder'].includes(location.hash))requestAnimationFrame(()=>document.querySelector(location.hash)?.scrollIntoView());}addEventListener('hashchange',activateHash);
$$('#mainnav a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',ev=>{if(ev.key==='Escape')closeMenu();});
makeICT();renderAll();setRegion(state.region);filterResources();activateHash();if(!privacyChoice)openConsent();
